Soru: 200 TL'lik bir ürüne %15 indirim uygulayıp yeni fiyatı hesaplayan C# satırlarını yazınız.

Çözüm:
double fiyat = 200.0;
double indirimTutari = fiyat * 0.15;
double odenecek = fiyat - indirimTutari;
lblSonuc.Text = odenecek.ToString("0.00") + " TL";

private void btnFisKes_Click(object sender, EventArgs e)
{
    try
    {
        // 1. Güvenli Okuma ve Dönüşüm
        double litreFiyati = Convert.ToDouble(txtLitreFiyat.Text);
        double alinanLitre = Convert.ToDouble(txtAlinanLitre.Text);

        // 2. Matematiksel Hesaplamalar
        double araToplam = litreFiyati * alinanLitre;
        double kdvTutari = araToplam * 0.20; // %20 KDV
        double genelToplam = araToplam + kdvTutari;

        // 3. Formatlı Yazdırma
        lblAraToplam.Text = "Ara Toplam : " + araToplam.ToString("0.00") + " TL";
        lblKdv.Text       = "KDV (%20)   : " + kdvTutari.ToString("0.00") + " TL";
        lblGenelToplam.Text = "ÖDENECEK   : " + genelToplam.ToString("0.00") + " TL";
        lblGenelToplam.ForeColor = Color.DarkGreen;
    }
    catch
    {
        MessageBox.Show("Lütfen litre fiyatı ve miktarını doğru girdiğinizden emin olun!", 
                        "Girdi Hatası", MessageBoxButtons.OK, MessageBoxIcon.Warning);
    }
}

